package io.knowledgebrain.knowledge;
import java.time.*;
import java.nio.file.*;
import java.util.*;
import org.apache.kafka.clients.consumer.*;
import org.apache.kafka.common.serialization.*;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import io.knowledgebrain.contracts.knowledge.publicrecord.v1.*;
import tools.jackson.databind.json.JsonMapper;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.assertj.core.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_KNOWLEDGE_KAFKA_BOOTSTRAP",matches=".+")
class PublicRecordKafkaIntegrationTest {
    @Test void actualDebeziumPublishesExactPublicSnapshotsAndProposalOrder()throws Exception{
        var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_URL"));ds.setUser("brain_knowledge");ds.setPassword(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_PASSWORD"));var ids=new UuidV7(Clock.systemUTC());var store=new PublicRecordStore(ds,Clock.systemUTC());UUID space=ids.next(),author=ids.next(),reviewer=ids.next();String trace="d".repeat(32);
        var content=JsonMapper.builder().build().createObjectNode().put("title","CDC public source").put("url","https://example.org/original").put("citation","Original metadata").put("licenseNote","Metadata only");
        var p=store.submit(space,author,"SOURCE","CREATE",null,0,"CDC public source",content,"Explicit public metadata",trace);store.decide(space,p.proposalId(),reviewer,1,"APPROVED","Checked",trace);store.decide(space,p.proposalId(),reviewer,2,"MERGED","Merge",trace);
        var expected=new HashMap<String,byte[]>();new JdbcTemplate(ds).query("SELECT id,payload FROM outbox_event WHERE aggregatetype='public-record' AND aggregateid IN (?,?)",(r,n)->{expected.put(r.getObject(1,UUID.class).toString(),r.getBytes(2));return 0;},p.proposalId(),p.recordId());assertThat(expected).hasSize(4);
        var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_KNOWLEDGE_KAFKA_BOOTSTRAP"));options.put("group.id","knowledge-validation-"+ids.next());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/knowledge-kafka-test/ca.crt")));options.put("ssl.keystore.type","PEM");options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/knowledge-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/knowledge-kafka-test/user.key")));
        try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("knowledge.public-record.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(90).toNanos();
            while(found.size()<expected.size()&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofSeconds(1))){if(!Set.of(p.proposalId().toString(),p.recordId().toString()).contains(record.key()))continue;var envelope=EventEnvelopeV1.parseFrom(record.value());assertThat(expected).containsKey(envelope.getEventId());assertThat(record.value()).isEqualTo(expected.get(envelope.getEventId()));assertThat(record.key()).isEqualTo(envelope.getAggregateId());assertThat(envelope.getSpaceId()).isEqualTo(space.toString());assertThat(envelope.getTraceId()).isEqualTo(trace);assertThat(new String(record.headers().lastHeader("trace_id").value())).isEqualTo(trace);assertThat(new String(record.headers().lastHeader("schema_group").value())).isEqualTo("knowledge");assertThat(new String(record.headers().lastHeader("schema_artifact").value())).isEqualTo("public-record-events");assertThat(new String(record.headers().lastHeader("schema_version").value())).isEqualTo("1");var payload=PublicRecordChangedPayloadV1.parseFrom(envelope.getPayload());assertThat(payload.getKind()).isEqualTo("SOURCE");assertThat(payload.getAuthorId()).isEqualTo(author.toString());assertThat(JsonMapper.builder().build().readTree(payload.getContentJson())).isEqualTo(content);if(found.add(envelope.getEventId())&&record.key().equals(p.proposalId().toString()))versions.add(payload.getVersion());}
            assertThat(found).containsExactlyInAnyOrderElementsOf(expected.keySet());assertThat(versions).containsExactly(1L,2L,3L);
        }
    }
    @Test void actualNormalizedPublicStreamPreservesQualifierProposalAndCanonicalBytes()throws Exception{
        var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_URL"));ds.setUser("brain_knowledge");ds.setPassword(System.getenv("BRAIN_TEST_KNOWLEDGE_DATABASE_PASSWORD"));var ids=new UuidV7(Clock.systemUTC());var store=new PublicRecordStore(ds,Clock.systemUTC());var concepts=new ConceptStore(ds,Clock.systemUTC());UUID space=ids.next(),author=ids.next(),reviewer=ids.next();String trace="d".repeat(32);var json=JsonMapper.builder().build();
        var a=concepts.createWithId(space,ids.next(),reviewer,"Public subject","",trace,"PUBLIC");var b=concepts.createWithId(space,ids.next(),reviewer,"Public predicate","",trace,"PUBLIC");var privateId=concepts.create(space,author,"Private CDC","",trace).conceptId();
        var claim=store.submit(space,author,"CLAIM","CREATE",null,0,"Public CDC Claim",json.createObjectNode().put("subjectId",a.conceptId().toString()).put("subjectVersion",1).put("predicateId",b.conceptId().toString()).put("predicateVersion",1).put("objectType","BOOLEAN").put("objectValue","true").put("objectVersion",0),"Explicit public test",trace);store.decide(space,claim.proposalId(),reviewer,1,"APPROVED","Checked",trace);store.decide(space,claim.proposalId(),reviewer,2,"MERGED","Merge",trace);
        var q=store.submit(space,author,"QUALIFIER","CREATE",null,0,"Public CDC scope",json.createObjectNode().put("claimId",claim.recordId().toString()).put("claimVersion",1).put("predicateId",b.conceptId().toString()).put("predicateVersion",1).put("valueType","DATE").put("value","2026-11-01").put("valueVersion",0),"Explicit scope",trace);store.decide(space,q.proposalId(),reviewer,1,"APPROVED","Checked",trace);store.decide(space,q.proposalId(),reviewer,2,"MERGED","Merge",trace);
        var sql=new JdbcTemplate(ds);assertThat(sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='public-knowledge' AND aggregateid=?",Integer.class,privateId)).isZero();var expected=new HashMap<String,byte[]>();sql.query("SELECT id,payload FROM outbox_event WHERE aggregatetype='public-knowledge' AND aggregateid IN (?,?,?,?,?)",(rs,n)->{expected.put(rs.getObject(1,UUID.class).toString(),rs.getBytes(2));return 0;},a.conceptId(),b.conceptId(),claim.recordId(),q.recordId(),q.proposalId());assertThat(expected).hasSize(7);
        var options=new Properties();options.put("bootstrap.servers",System.getenv("BRAIN_TEST_KNOWLEDGE_KAFKA_BOOTSTRAP"));options.put("group.id","knowledge-validation-"+ids.next());options.put("enable.auto.commit","false");options.put("auto.offset.reset","earliest");options.put("key.deserializer",StringDeserializer.class.getName());options.put("value.deserializer",ByteArrayDeserializer.class.getName());options.put("security.protocol","SSL");options.put("ssl.endpoint.identification.algorithm","HTTPS");options.put("ssl.truststore.type","PEM");options.put("ssl.truststore.certificates",Files.readString(Path.of("/knowledge-kafka-test/ca.crt")));options.put("ssl.keystore.type","PEM");options.put("ssl.keystore.certificate.chain",Files.readString(Path.of("/knowledge-kafka-test/user.crt")));options.put("ssl.keystore.key",Files.readString(Path.of("/knowledge-kafka-test/user.key")));

        try(var consumer=new KafkaConsumer<String,byte[]>(options)){consumer.subscribe(List.of("knowledge.public-knowledge.v1"));var found=new HashSet<String>();var versions=new ArrayList<Long>();long deadline=System.nanoTime()+Duration.ofSeconds(90).toNanos();while(found.size()<expected.size()&&System.nanoTime()<deadline)for(var record:consumer.poll(Duration.ofSeconds(1))){var envelope=io.knowledgebrain.contracts.knowledge.publicknowledge.v1.EventEnvelopeV1.parseFrom(record.value());if(!expected.containsKey(envelope.getEventId()))continue;assertThat(record.value()).isEqualTo(expected.get(envelope.getEventId()));assertThat(envelope.getSpaceId()).isEqualTo(space.toString());assertThat(record.key()).isEqualTo(envelope.getAggregateId());assertThat(envelope.getTraceId()).isEqualTo(trace);assertThat(new String(record.headers().lastHeader("schema_artifact").value())).isEqualTo("public-knowledge-events");assertThat(new String(record.headers().lastHeader("trace_id").value())).isEqualTo(trace);var payload=io.knowledgebrain.contracts.knowledge.publicknowledge.v1.PublicKnowledgeChangedPayloadV1.parseFrom(envelope.getPayload());assertThat(payload.getVisibility()).isEqualTo("PUBLIC");if(found.add(envelope.getEventId())&&record.key().equals(q.proposalId().toString()))versions.add(payload.getVersion());}assertThat(found).containsExactlyInAnyOrderElementsOf(expected.keySet());assertThat(versions).containsExactly(1L,2L,3L);}
    }

}
